"""Naive protocol-3.0 reference: plain lists, O(n) lag walks, deep checkpoints.
Used only to cross-check the optimized submission engine."""
import bisect


def migrate(vec, old, new):
    Rn = len(new) - 1
    out = [0] * Rn
    for j in range(len(vec)):
        m = vec[j]
        if not m:
            continue
        b = old[j]; c = old[j + 1]; w = c - b

        def g(x):
            y = x - b
            if y < 0: y = 0
            elif y > w: y = w
            return (m * y) // w
        for s in range(Rn):
            out[s] += g(new[s + 1]) - g(new[s])
    return out


class Ref:
    def __init__(self, spec):
        self.M = spec['banks']; self.L = spec['load_balancers']
        self.fcap = spec['fifo_bytes']; self.pcap = spec['pifo_bytes']
        self.batch = spec['refill_batch']; self.period = spec['sample_period']
        self.borders = list(spec['borders']); self.R = len(self.borders) - 1
        pol = spec['policy']; kind = pol['kind']
        self.kind = kind
        if kind == 'fifo':
            self.time = 0
        elif kind == 'sp':
            self.levels = dict((f, v) for f, v in pol['levels'])
        elif kind == 'wfq':
            self.weights = dict((f, w) for f, w in pol['weights'])
            self.finish = dict((f, 0) for f in self.weights)
            self.V = 0
        self.t = 0; self.p = 0; self.l = 0; self.a = 0
        self.C = [[[1 if q < (r % self.M) else 0 for r in range(self.R)]
                   for q in range(self.M)] for l in range(self.L)]
        self.H = [0] * self.R
        self.fifo = [[] for _ in range(self.M)]      # packet dicts
        self.fbytes = [0] * self.M
        self.pifo = [[] for _ in range(self.M)]      # sorted by (rank, ord)
        self.pbytes = [0] * self.M
        self.live = []                               # all staged+resident
        self.reg = {}

    # ------------------------------------------------------------------ policy
    def rank(self, flow, length, fsize):
        k = self.kind
        if k == 'fifo':
            self.time += 1
            return self.time
        if k == 'sp':
            return self.levels.get(flow, 0)
        if k == 'sff':
            return fsize
        w = self.weights.get(flow, 1)
        tag = max(self.finish.get(flow, 0), self.V)
        tag += (length * 1048576 + w - 1) // w
        self.finish[flow] = tag
        return tag

    def post(self, rank):
        if self.kind == 'wfq' and rank > self.V:
            self.V = rank

    # ----------------------------------------------------------------- helpers
    def classify(self, rank):
        b = self.borders
        c = min(rank, b[-1] - 1)
        if c < 0:
            c = 0
        return bisect.bisect_right(b, c) - 1

    def refill(self, q):
        ev = []
        k = min(self.batch, len(self.fifo[q]))
        for _ in range(k):
            pkt = self.fifo[q].pop(0)
            self.fbytes[q] -= pkt['len']
            self.pifo[q].append(pkt)
            self.pifo[q].sort(key=lambda p: (p['rank'], p['ord']))
            self.pbytes[q] += pkt['len']
        total = sum(p['len'] for p in self.pifo[q])
        keep = []
        acc = 0
        for p in self.pifo[q]:
            if acc + p['len'] <= self.pcap:
                keep.append(p); acc += p['len']
            else:
                break
        self.pifo[q] = keep
        self.pbytes[q] = acc
        gone = [p for p in sorted(self.live,
                                  key=lambda p: (p['rank'], p['ord']),
                                  reverse=True) if p not in keep
                and p['stage'] == 'pifo' and p['bank'] == q]
        for p in gone:
            self.live.remove(p)
            ev.append(p['id'])
        return ev

    def serve(self, q, pkt, ev, i, old_t, log):
        self.pbytes[q] -= pkt['len']
        self.post(pkt['rank'])
        rerr = sum(1 for p in self.live if p['rank'] < pkt['rank'])
        self.live.remove(pkt)
        for p in self.live:
            if p['rank'] < pkt['rank']:
                p['lag'] += 1
        log.append([i, 'dequeue', old_t, q, pkt['id'], pkt['rank'], rerr,
                    pkt['lag'], ev])

    def sample(self, i, log):
        R = self.R
        X = [0] * R
        for r in range(R):
            X[r] = sum(self.C[l][q][r] for l in range(self.L)
                       for q in range(self.M))
        for l in range(self.L):
            for r in range(R):
                m = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= m
        for r in range(R):
            self.H[r] = self.H[r] // 2 + X[r]
        self.a = 0
        log.append([i, 'sample', X, list(self.H)])

    def snapshot(self):
        def cp(pkt):
            return dict(pkt)
        return {'t': self.t, 'p': self.p, 'l': self.l, 'a': self.a,
                'borders': list(self.borders), 'R': self.R,
                'H': list(self.H),
                'C': [[list(row) for row in lb] for lb in self.C],
                'fifo': [[cp(p) for p in f] for f in self.fifo],
                'fbytes': list(self.fbytes),
                'pifo': [[cp(p) for p in f] for f in self.pifo],
                'pbytes': list(self.pbytes),
                'live': [cp(p) for p in self.live],
                'policy': self.polsnap()}

    def polsnap(self):
        k = self.kind
        if k == 'fifo':
            return self.time
        if k == 'wfq':
            return (self.V, dict(self.weights), dict(self.finish))
        return None

    def polrestore(self, s):
        k = self.kind
        if k == 'fifo':
            self.time = s
        elif k == 'wfq':
            self.V, self.weights, self.finish = s

    def restore(self, s):
        self.t = s['t']; self.p = s['p']; self.l = s['l']; self.a = s['a']
        self.borders = list(s['borders']); self.R = s['R']
        self.H = list(s['H']); self.C = s['C']
        self.fifo = s['fifo']; self.fbytes = s['fbytes']
        self.pifo = s['pifo']; self.pbytes = s['pbytes']
        self.live = s['live']
        self.polrestore(s['policy'])

    # ----------------------------------------------------------------- driver
    def run(self, events):
        log = []
        snaps = {}
        for i, ev in enumerate(events):
            op = ev[0]
            if op == 'enqueue':
                _, pid, flow, length, fsize = ev
                rank = self.rank(flow, length, fsize)
                r = self.classify(rank)
                lb = self.l; self.l = (self.l + 1) % self.L
                best = None; q = 0
                for cand in range(self.M):
                    v = self.C[lb][cand][r]
                    if best is None or v < best:
                        best = v; q = cand
                if self.fbytes[q] + length <= self.fcap:
                    pkt = {'id': pid, 'flow': flow, 'len': length,
                           'rank': rank, 'ord': i, 'bank': q, 'lag': 0,
                           'stage': 'fifo'}
                    self.fifo[q].append(pkt)
                    self.fbytes[q] += length
                    self.C[lb][q][r] += 1
                    self.a += 1
                    self.live.append(pkt)
                    self.reg[pid] = pkt
                    log.append([i, 'enqueue', pid, rank, lb, r, q, True])
                    if self.a == self.period:
                        self.sample(i, log)
                else:
                    log.append([i, 'enqueue', pid, rank, lb, r, q, False])
            elif op == 'dequeue':
                for _ in range(ev[1]):
                    old_t = self.t
                    q = self.p; self.p = (self.p + 1) % self.M
                    self.t = old_t + 1
                    if self.pifo[q]:
                        pkt = self.pifo[q].pop(0)
                        ev = self.refill(q)
                        self.serve(q, pkt, ev, i, old_t, log)
                    else:
                        ev = self.refill(q)
                        if self.pifo[q]:
                            pkt = self.pifo[q].pop(0)
                            self.serve(q, pkt, ev, i, old_t, log)
                        else:
                            log.append([i, 'dequeue', old_t, q, None, None,
                                        0, 0, ev])
            elif op == 'sample':
                self.sample(i, log)
            elif op == 'repartition':
                new = list(ev[1])
                self.C = [[migrate(row, self.borders, new)
                           for row in lb] for lb in self.C]
                self.H = migrate(self.H, self.borders, new)
                self.borders = new
                self.R = len(new) - 1
                log.append([i, 'repartition', self.R])
            elif op == 'cancel':
                pid = ev[1]
                pkt = self.reg.get(pid)
                row = [i, 'cancel', pid, None, None, None]
                if pkt is not None and pkt in self.live:
                    lag = pkt['lag']
                    if pkt['stage'] == 'pifo':
                        row = [i, 'cancel', pid, 'pifo', pkt['bank'], lag]
                        self.pifo[pkt['bank']].remove(pkt)
                        self.pbytes[pkt['bank']] -= pkt['len']
                    else:
                        row = [i, 'cancel', pid, 'fifo', pkt['bank'], lag]
                        self.fifo[pkt['bank']].remove(pkt)
                        self.fbytes[pkt['bank']] -= pkt['len']
                    self.live.remove(pkt)
                log.append(row)
            elif op == 'inspect':
                pid = ev[1]
                pkt = self.reg.get(pid)
                rec = None
                if pkt is not None and pkt in self.live:
                    rec = [pkt['rank'], pkt['bank'], pkt['stage'], pkt['len'],
                           pkt['flow'], pkt['lag']]
                log.append([i, 'inspect', pid, rec])
            elif op == 'weight':
                if self.kind == 'wfq':
                    self.weights[ev[1]] = ev[2]
                    self.finish.setdefault(ev[1], 0)
                log.append([i, 'weight', ev[1], ev[2]])
            elif op == 'save':
                snaps[ev[1]] = self.snapshot()
                log.append([i, 'save', ev[1]])
            elif op == 'restore':
                if ev[1] in snaps:
                    self.restore(snaps[ev[1]])
                log.append([i, 'restore', ev[1]])
        return log

    def state(self):
        queues = []
        for q in range(self.M):
            queues.append({'fifo': [p['id'] for p in self.fifo[q]],
                           'pifo': [p['id'] for p in self.pifo[q]],
                           'fifo_bytes': self.fbytes[q],
                           'pifo_bytes': self.pbytes[q]})
        lags = sorted(([p['id'], p['lag']] for p in self.live),
                      key=lambda x: x[0])
        pol = {'kind': self.kind}
        if self.kind == 'fifo':
            pol = {'kind': 'fifo', 'time': self.time}
        elif self.kind == 'sp':
            pol = {'kind': 'sp', 'levels': [list(x) for x in
                                            sorted(self.levels.items())]}
        elif self.kind == 'wfq':
            pol = {'kind': 'wfq', 'virtual_time': self.V,
                   'weights': [list(x) for x in sorted(self.weights.items())],
                   'finish': [list(x) for x in sorted(self.finish.items())]}
        return {'tick': self.t, 'load_balancer': self.l,
                'service_bank': self.p, 'sample_progress': self.a,
                'borders': list(self.borders),
                'counters': [[[list(row) for row in lb] for lb in self.C]][0]
                if False else [[list(row) for row in lb] for lb in self.C],
                'history': list(self.H), 'policy': pol, 'queues': queues,
                'lags': lags}


def run(spec):
    eng = Ref(spec)
    return {'log': eng.run(spec['events']), 'state': eng.state()}
